    test('formats seconds, minutes and hours', () {
      expect(formatTimeLeft(45 * 1000), '45s');
      expect(formatTimeLeft(5 * 60 * 1000), '5min');
      expect(formatTimeLeft(60 * 60 * 1000), '1h');
      expect(formatTimeLeft(90 * 60 * 1000), '1h30m');
